<body>
<div class="wrap">
  <h1>Duna-kvíz</h1>
  <p class="lede">10 kérdés Európa legismertebb folyójáról. Válassz egy választ a négy közül, majd lépj a következőre.</p>
  <div id="app"></div>
  <p class="sr" id="status" aria-live="polite"></p>
</div>
<script>
const QUESTIONS = [
  {q:"Melyik országban ered a Duna?", opts:["Németország","Ausztria","Magyarország","Szlovákia"], a:0},
  {q:"Hány ország fővárosán halad át a Duna?", opts:["Kettő","Három","Négy","Öt"], a:2},
  {q:"Melyik tengerbe ömlik a Duna?", opts:["Fekete-tenger","Balti-tenger","Adria","Északi-tenger"], a:0},
  {q:"Melyik a Duna leghosszabb magyarországi mellékfolyója?", opts:["Tisza","Dráva","Rába","Száva"], a:0},
  {q:"Melyik híres budapesti híd a Duna felett?", opts:["Szabadság híd","Hősök tere","Városliget","Gellért-hegy"], a:0},
  {q:"Melyik városban találkozik a Duna a Szávával?", opts:["Belgrád","Budapest","Bécs","Bratislava"], a:0},
  {q:"Melyik híres keringő született a Duna ihletésére?", opts:["A kék Duna keringő","Für Elise","Czár-dás","Csárdás"], a:0},
  {q:"Melyik országban fekszik a Duna-delta?", opts:["Románia","Ukrajna","Bulgária","Szerbia"], a:0},
  {q:"Hány ország területén folyik keresztül a Duna?", opts:["10","7","12","5"], a:0},
  {q:"Melyik a Duna legmagasabb vízesése?", opts:["Rheinfall","Gellért-vízesés","Széchenyi-vízesés","Tisza-vízesés"], a:0}
];
const TOTAL = QUESTIONS.length;
const LETTERS = ['A','B','C','D'];
const KEY = 'duna-quiz';

const app = document.getElementById('app');
const statusEl = document.getElementById('status');

let state = {screen:'intro', idx:0, answers:[], best:null};

function announce(msg){ statusEl.textContent = msg; }

function save(){
  if (window.alfy && window.alfy.storage){
    try { window.alfy.storage.set(KEY, state); } catch(e){}
  }
}

function esc(s){ return String(s).replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c])); }

function render(){
  if (state.screen === 'intro') return renderIntro();
  if (state.screen === 'result') return renderResult();
  renderQuestion();
}

function renderIntro(){
  const best = state.best != null ? `<p class="hint">Legjobb eddigi eredményed: <strong>${state.best} / ${TOTAL}</strong>.</p>` : '';
  app.innerHTML = `
    <div class="card">
      <h2 class="qtext">Készen állsz?</h2>
      <p class="empty">Ez a kvíz <strong>${TOTAL} kérdést</strong> tartalmaz a Dunáról, mindegyikhez négy válaszlehetőséggel. A végén megkapod a pontszámod.</p>
      ${best}
      <div class="actions">
        <button type="button" class="btn primary" id="startBtn">Kvíz indítása</button>
      </div>
    </div>`;
  document.getElementById('startBtn').addEventListener('click', startQuiz);
}

function startQuiz(){
  state.screen = 'quiz'; state.idx = 0; state.answers = new Array(TOTAL).fill(null);
  save(); render();
}

function renderQuestion(){
  const i = state.idx, item = QUESTIONS[i];
  const answered = state.answers.filter(a => a !== null).length;
  const pct = Math.round((answered / TOTAL) * 100);
  const opts = item.opts.map((text, oi) => {
    const sel = state.answers[i] === oi;
    return `<button type="button" class="opt${sel ? ' sel' : ''}" data-oi="${oi}" aria-pressed="${sel}">
      <span class="key" aria-hidden="true">${LETTERS[oi]}</span><span>${esc(text)}</span>
    </button>`;
  }).join('');
  const last = i === TOTAL - 1;
  const done = state.answers[i] !== null;

  app.innerHTML = `
    <div class="card">
      <div class="bar" aria-hidden="true"><i style="width:${pct}%"></i></div>
      <div class="meta"><span class="qno">${i + 1}. kérdés</span><span>${answered} / ${TOTAL} megválaszolva</span></div>
      <h2 class="qtext">${esc(item.q)}</h2>
      <div class="opts" role="group" aria-label="Válaszlehetőségek">${opts}</div>
      <div class="actions">
        <button type="button" class="btn" id="prevBtn" ${i === 0 ? 'disabled' : ''}>Előző</button>
        <button type="button" class="btn primary" id="nextBtn" ${done ? '' : 'disabled'}>${last ? 'Eredmény' : 'Következő'}</button>
      </div>
      <p class="hint">Válassz egy választ a folytatáshoz. A válasz bármikor módosítható.</p>
    </div>`;

  app.querySelectorAll('.opt').forEach(btn => {
    btn.addEventListener('click', () => {
      state.answers[i] = parseInt(btn.dataset.oi, 10);
      save(); render();
    });
  });
  document.getElementById('prevBtn').addEventListener('click', () => {
    if (state.idx > 0){ state.idx--; save(); render(); }
  });
  document.getElementById('nextBtn').addEventListener('click', () => {
    if (state.answers[i] === null) return;
    if (last){ finish(); }
    else { state.idx++; save(); render(); }
  });
  announce(`${i + 1}. kérdés: ${item.q}`);
}

function finish(){
  let score = 0;
  for (let i = 0; i < TOTAL; i++){ if (state.answers[i] === QUESTIONS[i].a) score++; }
  state.screen = 'result'; state.score = score;
  if (state.best == null || score > state.best) state.best = score;
  save(); render();
}

function verdict(score){
  const r = score / TOTAL;
  if (r >= 0.9) return 'Kiváló! Te igazi Duna-szakértő vagy.';
  if (r >= 0.7) return 'Nagyon jó eredmény, alig maradt ki.';
  if (r >= 0.5) return 'Közepes eredmény – még van mit tanulni a Dunáról.';
  return 'Ez most kevés volt, de próbáld újra!';
}

function renderResult(){
  const score = state.score;
  const items = QUESTIONS.map((item, i) => {
    const given = state.answers[i];
    const ok = given === item.a;
    const givenTxt = given == null ? 'Nem válaszoltál' : LETTERS[given] + '. ' + esc(item.opts[given]);
    return `<li>
      <div class="bq">${i + 1}. ${esc(item.q)}</div>
      <div class="brow"><span class="mark ${ok ? 'ok' : 'no'}" aria-hidden="true">${ok ? '✓' : '✕'}</span><span>A te válaszod: ${givenTxt}</span></div>
      ${ok ? '' : `<div class="bans">Helyes válasz: <b>${LETTERS[item.a]}. ${esc(item.opts[item.a])}</b></div>`}
    </li>`;
  }).join('');

  app.innerHTML = `
    <div class="card center">
      <p class="empty" style="margin-bottom:0">A kvíz vége</p>
      <div class="score">${score} / ${TOTAL}</div>
      <p class="verdict">${esc(verdict(score))}</p>
      <ul class="breakdown">${items}</ul>
      <div class="actions">
        <button type="button" class="btn primary" id="againBtn">Újra</button>
        <button type="button" class="btn" id="homeBtn">Kezdőoldal</button>
      </div>
    </div>`;
  document.getElementById('againBtn').addEventListener('click', startQuiz);
  document.getElementById('homeBtn').addEventListener('click', () => { state.screen = 'intro'; save(); render(); });
  announce(`Kész. Pontszámod ${score} a ${TOTAL}-ból.`);
}

async function load(){
  if (window.alfy && window.alfy.storage){
    try {
      const s = await window.alfy.storage.get(KEY);
      if (s && typeof s === 'object'){
        state.best = (typeof s.best === 'number') ? s.best : null;
      }
    } catch(e){}
  }
  render();
}
load();
</script>
</body>
</html>
